<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require __DIR__.'/../app/admin_shell.php';
security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$admin=current_admin();$adminId=(int)($admin['id']??0);$processId=max(0,(int)($_GET['id']??$_POST['process_id']??0));

function admin_processes_url(int $processId=0,array $extra=[]): string {$args=$extra;if($processId>0)$args=['id'=>$processId]+$args;return '/admin/processes.php'.($args?'?'.http_build_query($args):'');}
function admin_process_step_input(array $step): array {$payload=student_process_json_array((string)($step['payload_json']??'{}'));return $payload+['stage_key'=>(string)($step['stage_key']??''),'duration'=>(string)($step['duration']??''),'agitation_interval'=>(string)($step['agitation_interval']??'')];}

if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('admin-processes',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}
    $action=(string)($_POST['action']??'');
    try{
        if($action==='create'){$created=student_global_process_create($db,$adminId,$_POST);$processId=(int)$created['id'];$_SESSION['admin_process_notice']='Processo criado como rascunho.';}
        elseif($action==='create_draft'){student_global_process_ensure_draft($db,$processId,$adminId);$_SESSION['admin_process_notice']='Nova versão em rascunho criada.';}
        elseif($action==='save_meta'){student_global_process_update_draft($db,(int)($_POST['version_id']??0),$adminId,$_POST);$_SESSION['admin_process_notice']='Rascunho salvo.';}
        elseif($action==='add_step'){student_global_process_add_step($db,(int)($_POST['version_id']??0),$adminId,$_POST);$_SESSION['admin_process_notice']='Etapa adicionada.';}
        elseif($action==='update_step'){student_global_process_update_step($db,(int)($_POST['version_id']??0),(int)($_POST['step_id']??0),$adminId,$_POST);$_SESSION['admin_process_notice']='Etapa atualizada.';}
        elseif($action==='delete_step'){student_global_process_delete_step($db,(int)($_POST['version_id']??0),(int)($_POST['step_id']??0),$adminId);$_SESSION['admin_process_notice']='Etapa removida do rascunho.';}
        elseif($action==='move_step'){student_global_process_move_step($db,(int)($_POST['version_id']??0),(int)($_POST['step_id']??0),$adminId,(int)($_POST['direction']??0));$_SESSION['admin_process_notice']='Ordem atualizada.';}
        elseif($action==='publish'){student_global_process_publish($db,(int)($_POST['version_id']??0),$adminId);$_SESSION['admin_process_notice']='Nova versão publicada. Registros existentes não foram alterados.';}
        elseif($action==='archive'){student_global_process_archive($db,$processId,$adminId,true);$_SESSION['admin_process_notice']='Processo arquivado para novos usos. O histórico foi preservado.';}
        elseif($action==='restore'){student_global_process_archive($db,$processId,$adminId,false);$_SESSION['admin_process_notice']='Processo reativado.';}
        else throw new RuntimeException('Ação inválida.');
    }catch(Throwable $e){$_SESSION['admin_process_notice']='Não foi possível concluir: '.$e->getMessage();}
    header('Location: '.admin_processes_url($processId),true,303);exit;
}

$processes=student_global_processes($db,true);$selected=$processId>0?student_global_process_by_id($db,$processId):null;$versions=$selected?student_global_process_versions($db,$processId):[];$draft=$selected?student_global_process_draft($db,$processId):null;$active=$selected&&(int)($selected['active_version_id']??0)>0?student_global_process_version($db,(int)$selected['active_version_id']):null;$draftSteps=$draft?student_global_process_version_steps($db,(int)$draft['id']):[];$activeSteps=$active?student_global_process_version_steps($db,(int)$active['id']):[];$stageCatalog=student_process_stage_catalog();$developerCatalog=student_process_developer_catalog();$notice=(string)($_SESSION['admin_process_notice']??'');unset($_SESSION['admin_process_notice']);$noticeTone=str_starts_with($notice,'Não foi possível')?'error':'success';

admin_shell_start('processes','Processos globais',$state,['/assets/admin-processes.css']);?>
<?php if($notice!==''):?><div class="admin-notice <?=h($noticeTone)?>" role="<?=$noticeTone==='error'?'alert':'status'?>"><?=h($notice)?></div><?php endif;?>

<?php if($selected):?>
<section class="admin-card admin-process-detail">
<header><div><a class="admin-back" href="/admin/processes.php">← Processos globais</a><p class="admin-kicker">Processo global</p><h2><?=h((string)$selected['name'])?></h2><p><?=h((string)$selected['description'])?></p><div class="admin-process-meta"><?=admin_badge((string)$selected['status']==='archived'?'Arquivado':'Ativo',(string)$selected['status']==='archived'?'muted':'good')?><?php if($active):?><span>Versão publicada v<?=(int)$active['version_number']?></span><?php else:?><span>Ainda não publicado</span><?php endif;?></div></div><div class="admin-card-actions"><?php if((string)$selected['status']==='archived'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="process_id" value="<?=$processId?>"><button class="admin-button secondary" type="submit">Reativar</button></form><?php elseif($active):?><form method="post" data-confirm="Arquivar este processo para novos usos? Registros e versões existentes serão preservados."><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="process_id" value="<?=$processId?>"><button class="admin-button secondary" type="submit">Arquivar</button></form><?php endif;?></div></header>
</section>

<?php if(!$draft):?>
<section class="admin-card admin-process-version-start"><header><div><p class="admin-kicker"><?=$active?'Alteração segura':'Configuração inicial'?></p><h2><?=$active?'Criar uma nova versão':'Criar o primeiro rascunho'?></h2><p><?=$active?'A versão publicada continua imutável. O rascunho parte dela e só passa a valer para novas escolhas depois de publicado.':'Crie o rascunho, monte as etapas e publique quando estiver pronto.'?></p></div><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="create_draft"><input type="hidden" name="process_id" value="<?=$processId?>"><button class="admin-button" type="submit">Criar rascunho</button></form></header></section>
<?php else:?>
<section class="admin-card admin-process-editor">
<header><div><p class="admin-kicker">Rascunho · v<?=(int)$draft['version_number']?></p><h2>Editar próxima versão</h2><p>Estas alterações não afetam alunos até a publicação e nunca reescrevem processos que já foram associados ou executados.</p></div></header>
<form class="admin-form-grid" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="save_meta"><input type="hidden" name="process_id" value="<?=$processId?>"><input type="hidden" name="version_id" value="<?=(int)$draft['id']?>"><label class="admin-form-span-2">Nome<input name="name" maxlength="180" required value="<?=h((string)$draft['name'])?>"></label><label class="admin-form-span-2">Descrição<textarea name="description" rows="3"><?=h((string)$draft['description'])?></textarea></label><label class="admin-form-span-2">O que mudou nesta versão<textarea name="change_note" rows="2" placeholder="Ex.: corrige tempo do branqueamento e explicita reutilização do primeiro banho."><?=h((string)$draft['change_note'])?></textarea></label><div class="admin-form-actions"><button class="admin-button" type="submit">Salvar rascunho</button></div></form>
</section>

<section class="admin-card admin-process-steps"><header><div><p class="admin-kicker">Roteiro</p><h2><?=count($draftSteps)?> etapa<?=count($draftSteps)===1?'':'s'?></h2><p>A ordem e os parâmetros abaixo são exatamente a base do roteiro que será copiado para novos registros após a publicação.</p></div></header>
<?php if(!$draftSteps):?><div class="admin-empty compact">Nenhuma etapa. Adicione a primeira etapa abaixo.</div><?php else:?><ol class="admin-process-step-list"><?php foreach($draftSteps as $index=>$step):$input=admin_process_step_input($step);$developerKey=(string)($input['developer_key']??'');?><li class="admin-process-step"><div class="admin-process-step-summary"><span><?=str_pad((string)($index+1),2,'0',STR_PAD_LEFT)?></span><div><strong><?=h((string)$step['label'])?></strong><small><?=h(implode(' · ',array_filter([(string)($input['developer_name']??''),(string)$step['duration'],(string)($input['temperature']??'')])))?></small></div><div class="admin-inline-actions"><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="move_step"><input type="hidden" name="process_id" value="<?=$processId?>"><input type="hidden" name="version_id" value="<?=(int)$draft['id']?>"><input type="hidden" name="step_id" value="<?=(int)$step['id']?>"><button class="admin-button secondary admin-table-action" type="submit" name="direction" value="-1"<?=$index===0?' disabled':''?>>↑</button><button class="admin-button secondary admin-table-action" type="submit" name="direction" value="1"<?=$index===count($draftSteps)-1?' disabled':''?>>↓</button></form></div></div><details><summary>Editar etapa</summary><form class="admin-form-grid admin-process-step-form" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="update_step"><input type="hidden" name="process_id" value="<?=$processId?>"><input type="hidden" name="version_id" value="<?=(int)$draft['id']?>"><input type="hidden" name="step_id" value="<?=(int)$step['id']?>"><label class="admin-form-span-2">Etapa<select name="stage_key" required><?php foreach($stageCatalog as $key=>$stage):?><option value="<?=h($key)?>"<?=$key===(string)$step['stage_key']?' selected':''?>><?=h((string)$stage['label'])?></option><?php endforeach;?></select></label><label>Revelador<select name="developer_key"><option value="">—</option><?php foreach($developerCatalog as $key=>$dev):?><option value="<?=h($key)?>"<?=$key===$developerKey?' selected':''?>><?=h((string)$dev['label'])?></option><?php endforeach;?></select></label><label>Nome personalizado<input name="developer_name" value="<?=h((string)($input['developer_name']??''))?>"></label><label>Revelador / estoque (ml)<input type="number" step="0.1" min="0" name="developer_amount" value="<?=h((string)($input['developer_amount']??''))?>"></label><label>Água (ml)<input type="number" step="0.1" min="0" name="water_amount" value="<?=h((string)($input['water_amount']??''))?>"></label><label>Volume fresco (ml)<input type="number" step="0.1" min="0" name="fresh_volume" value="<?=h((string)($input['fresh_volume']??''))?>"></label><label>Temperatura<input name="temperature" value="<?=h((string)($input['temperature']??''))?>"></label><label>Tempo<input name="duration" value="<?=h((string)$step['duration'])?>" placeholder="7:00"></label><label>Intervalo de agitação<input name="agitation_interval" value="<?=h((string)$step['agitation_interval'])?>"></label><label class="admin-form-span-2">Agitação<input name="agitation" value="<?=h((string)($input['agitation']??''))?>"></label><label class="admin-form-span-2">Químico / nome livre<input name="chemical_name" value="<?=h((string)($input['chemical_name']??''))?>"></label><label>Reutilizar banho<select name="reuse_source_stage_key"><option value="">Não</option><option value="first_development"<?=((string)($input['reuse_source_stage_key']??'')==='first_development')?' selected':''?>>Primeira revelação</option></select></label><label class="admin-form-span-2">Notas<textarea name="notes" rows="3"><?=h((string)($input['notes']??''))?></textarea></label><div class="admin-form-actions admin-form-span-2"><button class="admin-button" type="submit">Salvar etapa</button></div></form><form method="post" class="admin-process-delete" data-confirm="Remover esta etapa apenas do rascunho?"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="delete_step"><input type="hidden" name="process_id" value="<?=$processId?>"><input type="hidden" name="version_id" value="<?=(int)$draft['id']?>"><input type="hidden" name="step_id" value="<?=(int)$step['id']?>"><button class="admin-button danger" type="submit">Remover etapa</button></form></details></li><?php endforeach;?></ol><?php endif;?>

<details class="admin-secondary-setup admin-process-add" open><summary class="admin-button secondary">Adicionar etapa</summary><form class="admin-form-grid" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('admin-processes'))?>"><input type="hidden" name="action" value="add_step"><input type="hidden" name="process_id" value="<?=$processId?>"><input type="hidden" name="version_id" value="<?=(int)$draft['id']?>"><label class="admin-form-span-2">Etapa<select name="stage_key" required><?php foreach($stageCatalog as $key=>$stage):?><option value="<?=h($key)"><?=h((string)$stage['label'])?></option><?php endforeach;?></select></label><label>Revelador<select name="developer_key"><option value="">—</option><?php foreach($developerCatalog as $key=>$dev):?><option value="<?=h($key)?>"><?=h((string)$dev['label'])?></option><?php endforeach;?></select></label><label>Nome personalizado<input name="developer_name"></label><label>Revelador / estoque (ml)<input type="number" step="0.1" min="0" name="developer_amount"></label><label>Água (ml)<input type="number" step="0.1" min="0" name="water_amount"></label><label>Volume fresco (ml)<input type="number" step="0.1" min="0" name="fresh_volume"></label><label>Temperatura<input name="temperature"></label><label>Tempo<input name="duration" placeholder="7:00"></label><label>Intervalo de agitação<input name="agitation_interval"></label><label class="admin-form-span-2">Agitação<input name="agitation"></label><label class="admin-form-span-2">Químico / nome livre<input name="chemical_name"></label><label>Reutilizar banho<select name="reuse_source_stage_key"><option value="">Não</option><option value="first_development">Primeira revelação</option></select></label><label class="admin-form-span-2">Notas<textarea name="notes" rows="3"></textarea></label><div class="admin-form-actions admin-form-span-2"><button class="admin-button" type="submit">Adicionar etapa</button></div></form></details>
</section>

